import six
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class ExtractStrategy(object):
    def __init__(self, addons_extractor, templates_extractor, paths_provider):
        self.addons = addons_extractor
        self.templates = templates_extractor
        self.paths = paths_provider

    @abstractmethod
    def extract(self, addons_path, destination):
        pass


class CommonStrategy(ExtractStrategy):
    def extract(self, addons_path, destination):
        self.addons.extract(archive=addons_path, destination=destination)
        templates_archive = self.paths.find_templates_archive(destination)
        self.templates.extract(archive=templates_archive,
                               destination=destination)
        return self.paths.find_templates_root_path(destination)
